const TAU=Math.PI*2;
export const TASK_ICONS={dirt:'🪥',plaque:'💦',food:'🪝',cavity:'🟣',loose:'↕',polish:'✨',missing:'🦷',candy:'🍬',crooked:'↻'};
const skins={mint:['#7ff1bc','#227c72'],berry:['#f19acb','#8d487e'],solar:['#ffd478','#be735a'],cosmic:['#ab96ff','#58468c'],moon:['#a294ec','#3e3a70'],bamboo:['#72e0bb','#28645a'],comet:['#f5b57a','#955d4e'],neon:['#79d9f3','#375d8c']};
function rounded(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke();}}
export function prepareCanvas(canvas){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);}const scale=Math.min(r.width/1000,r.height/640),ox=(r.width-scale*1000)/2,oy=(r.height-scale*640)/2,c=canvas.getContext('2d');c.setTransform(d,0,0,d,0,0);c.fillStyle='#0d172b';c.fillRect(0,0,r.width,r.height);c.setTransform(d*scale,0,0,d*scale,d*ox,d*oy);return{c,scale,ox,oy,r};}
function background(c,m,kind){drawBackdrop(c,kind==='dentist'?'dentist workshop':m.level.theme||kind,m.clock);}
function label(c,text,x,y,size=14,color='#cfdef0'){c.fillStyle=color;c.textAlign='center';c.textBaseline='middle';c.font=`600 ${size}px Outfit,Arial`;c.fillText(text,x,y);}
export function renderSlime(canvas,m,skin='mint'){const{c}=prepareCanvas(canvas);background(c,m,'slime');environment(c,m,'slime');sparkles(c,m);label(c,m.level.theme.toUpperCase(),500,35,15,'#86dcca');
 for(const r of m.geometry()){c.save();c.translate(r.x+r.w/2,r.y+r.h/2);c.rotate(r.angle||0);const colors={ground:'#34465a',platform:'#5377a1',moving:'#7771b1',wall:'#7864a1',rotator:'#ad81aa',sticky:'#c392bc',ice:'#88d5e5',conveyor:'#d0a86a',bounce:'#6bd5ac',passage:'#59657e'};rounded(c,-r.w/2,-r.h/2,r.w,r.h,Math.min(9,r.h/2),colors[r.kind]||'#546c86','#a2b1d055');drawMaterial(c,r.kind==='ice'?'ice':r.kind==='sticky'?'wood':'metal',-r.w/2,-r.h/2,r.w,r.h);if(r.kind==='conveyor')label(c,'› › › ›',0,0,18,'#523c3e');if(r.kind==='bounce')label(c,'⇡ ⇡ ⇡',0,0,20,'#245853');if(r.kind==='ice')label(c,'❄',0,0,16,'#efffff');c.restore();}
 for(const h of m.level.hazards){if(h.kind==='spikes'){c.fillStyle='#f29ab1';for(let x=h.x;x<h.x+h.w;x+=18){c.beginPath();c.moveTo(x,h.y+h.h);c.lineTo(x+9,h.y);c.lineTo(x+18,h.y+h.h);c.fill();}}else{const on=m.clock%h.period<h.on;c.globalAlpha=on?1:.2;c.strokeStyle='#ff86bc';c.lineWidth=on?8:3;c.shadowBlur=on?14:0;c.shadowColor='#ff6da9';c.beginPath();c.moveTo(h.x+h.w/2,h.y);c.lineTo(h.x+h.w/2,h.y+h.h);c.stroke();c.shadowBlur=0;c.globalAlpha=1;label(c,on?'LASER':'SAFE',h.x+h.w/2,h.y-15,12,on?'#ff99bc':'#83edc4');}}
 for(const z of m.level.zones){if(z.kind==='fan'){c.fillStyle='#70d8eb15';c.fillRect(z.x,z.y,z.w,z.h);label(c,'🌀',z.x+z.w/2,z.y+z.h,36);for(let i=0;i<4;i++)label(c,'↑',z.x+15+i*28,z.y+z.h-(m.clock/14+i*40)%z.h,28,'#8be6ec88');}else{c.strokeStyle='#b29cff';c.lineWidth=5;for(const p of [z,z.dest]){c.beginPath();c.ellipse(p.x+(p.w||0)/2,p.y+(p.h||0)/2,22,33,Math.sin(m.clock/500)*.2,0,TAU);c.stroke();}label(c,'WARP',z.x+17,z.y-15,12,'#d6bcff');}}
 m.level.pads.forEach((p,i)=>{rounded(c,p.x,p.y,p.w,p.h,8,m.padLatched?'#67ecc0':'#5d456b','#d1a4dc');label(c,m.padLatched?'✓':'BLOB '+(i+1),p.x+p.w/2,p.y+12,12,m.padLatched?'#174d43':'#f5d6fa');});
 m.level.orbs.forEach((o,i)=>{if(m.collected.has(i))return;if(o.secret&&!m.blobs.some(b=>dist(b.center,o)<170))return;c.save();c.translate(o.x,o.y);c.rotate(m.clock/800);c.shadowBlur=16;c.shadowColor=o.key?'#ffdc6d':'#8fead7';c.fillStyle=o.secret?'#d9a5ff':o.key?'#ffe18b':'#8ff3db';c.beginPath();for(let j=0;j<8;j++){const a=j*Math.PI/4,r=j%2?7:15;c.lineTo(Math.cos(a)*r,Math.sin(a)*r);}c.closePath();c.fill();c.restore();});
 const keys=m.level.orbs.every((o,i)=>!o.key||m.collected.has(i)),open=keys&&(!m.level.requiresSplit||m.padLatched&&m.mergeCount>0);rounded(c,m.level.exit.x,m.level.exit.y,m.level.exit.w,m.level.exit.h,18,open?'#7bd7b155':'#65547c55',open?'#89ffcc':'#ac91cd');label(c,open?'EXIT':'🔒',m.level.exit.x+32,m.level.exit.y+42,23,open?'#aeffdb':'#e1c6f3');
 for(const b of m.blobs){const center=b.center,[fill,stroke]=skins[skin]||skins.mint;c.save();c.shadowBlur=20;c.shadowColor=fill+'66';c.beginPath();const last=b.nodes.at(-1),first=b.nodes[0];c.moveTo((last.x+first.x)/2,(last.y+first.y)/2);for(let i=0;i<b.nodes.length;i++){const p=b.nodes[i],q=b.nodes[(i+1)%16];c.quadraticCurveTo(p.x,p.y,(p.x+q.x)/2,(p.y+q.y)/2);}c.closePath();c.fillStyle=fill;c.fill();c.lineWidth=3;c.strokeStyle=stroke;c.stroke();c.shadowBlur=0;c.fillStyle='#ecffdb66';c.beginPath();c.ellipse(center.x-b.radius*.35,center.y-b.radius*.42,b.radius*.16,b.radius*.3,-.5,0,TAU);c.fill();c.strokeStyle='#236e7533';c.lineWidth=4;c.beginPath();c.arc(center.x,center.y+b.radius*.25,b.radius*.63,.1,Math.PI-.1);c.stroke();if(skin==='berry')for(let i=0;i<5;i++){c.fillStyle='#fff4';c.beginPath();c.arc(center.x+(i-2)*8,center.y-12+(i%2)*7,3,0,TAU);c.fill();}c.fillStyle='#183443';for(const x of [-9,9]){c.beginPath();c.ellipse(center.x+x*Math.sqrt(b.mass),center.y-5,3,5,0,0,TAU);c.fill();}c.strokeStyle='#234451';c.lineWidth=3;c.beginPath();c.arc(center.x,center.y+2,9*Math.sqrt(b.mass),0,Math.PI);c.stroke();if(skin==='solar')label(c,'♛',center.x,center.y-b.radius-12,22,'#ffe4a1');if(skin==='cosmic')label(c,'✦',center.x-b.radius-10,center.y+Math.sin(m.clock/300)*20,20,'#cab5ff');for(const p of b.pins.values()){const dx=p.origin.x-p.x,dy=p.origin.y-p.y;c.setLineDash([5,6]);c.strokeStyle='#ffe1a1aa';c.lineWidth=3;c.beginPath();c.moveTo(center.x,center.y);c.lineTo(p.x,p.y);c.stroke();c.setLineDash([]);for(let j=1;j<14;j++){const t=j*.065;c.fillStyle='#e7fdd299';c.beginPath();c.arc(center.x+dx*6.3*t,center.y+dy*6.3*t+325*t*t,2.5,0,TAU);c.fill();}c.strokeStyle='#fff';c.lineWidth=2;c.beginPath();c.arc(p.x,p.y,10,0,TAU);c.stroke();}c.restore();}
}
export function renderNinja(canvas,m,skin='moon'){const{c}=prepareCanvas(canvas);background(c,m,'ninja');environment(c,m,'ninja');sparkles(c,m);label(c,m.level.theme.toUpperCase(),500,30,15,'#aaa6e7');
 for(const r of m.geometry())rounded(c,r.x,r.y,r.w,r.h,7,r.kind==='door'?'#b18d63':r.kind==='timedDoor'?'#916d99':'#4b557b','#a5acc444');
 for(const p of m.level.platforms){const x=p.x+Math.sin(m.clock/p.period*TAU)*p.range;rounded(c,x,p.y,p.w,p.h,8,p.kind==='collapse'?'#9f7891':'#69889e','#b7c4d6');label(c,p.kind==='collapse'?'…':'⇄',x+p.w/2,p.y+16,20);}
 for(const p of m.level.covers){rounded(c,p.x,p.y,p.w,p.h,18,'#38636b','#70a797');label(c,'✦',p.x+p.w/2,p.y+p.h/2,25,'#75a79f');}
 for(const l of m.level.lights){const a=l.angle+Math.sin(m.clock/l.period*TAU)*1.1;cone(c,l.x,l.y,a,l.cone,l.range,'#ffe29b26');label(c,'◉',l.x,l.y,28,'#ffe4a5');}
 for(const g of m.guards()){if(!g.stunned)cone(c,g.x,g.y,g.angle,g.cone,g.radius,'#ffad7730');rounded(c,g.x-16,g.y-18,32,36,12,g.stunned?'#6c6592':'#c4918d','#f3bfab');label(c,g.stunned?'💤':'• •',g.x,g.y-1,15);}
 for(const l of m.level.lasers){const on=m.clock%l.period<l.on;c.strokeStyle=on?'#ff86ad':'#77c9b344';c.lineWidth=on?5:2;c.setLineDash(on?[]:[7,7]);c.beginPath();c.moveTo(l.x,l.y);c.lineTo(l.x2,l.y2);c.stroke();c.setLineDash([]);label(c,on?'⚠':'SAFE',(l.x+l.x2)/2,l.y-14,12,on?'#ffbdd4':'#87dfbd');}
 for(const t of m.level.traps){c.globalAlpha=m.clock%t.period<t.on?.8:.2;c.strokeStyle='#ef9dc9';c.lineWidth=4;c.beginPath();c.arc(t.x,t.y,t.r,0,TAU);c.stroke();c.globalAlpha=1;}
 for(const p of m.level.plates){c.fillStyle=m.plateOn?'#70ebbd':'#ac92cd';c.beginPath();c.arc(p.x,p.y,p.r,0,TAU);c.fill();label(c,m.plateOn?'✓':'STEP',p.x,p.y,13,'#293249');}
 label(c,m.switchOn?'☀':'◈',m.level.switch.x,m.level.switch.y,36,m.switchOn?'#79f1c2':'#ffd67d');label(c,'STAR SWITCH',m.level.switch.x,m.level.switch.y+29,10,'#e5d7ad');
 m.level.scrolls.forEach((p,i)=>{if(!m.collected.has(i))label(c,p.key?'📜':'✦',p.x,p.y,28,p.key?'#ffe5a0':'#a7a5ed');});
 const open=m.level.scrolls.every((o,i)=>!o.key||m.collected.has(i))&&(!m.level.switch.required||m.switchOn)&&(!m.level.requiresPlate||m.plateOn);rounded(c,m.level.exit.x,m.level.exit.y,m.level.exit.w,m.level.exit.h,15,open?'#63c6a355':'#584b7755',open?'#7af2bf':'#ad97d8');label(c,open?'EXIT':'🔒',m.level.exit.x+30,m.level.exit.y+40,22);
 if(m.route.length||m.preview.length){c.strokeStyle=m.preview.length?'#ffe094':'#a89af5';c.lineWidth=3;c.setLineDash([6,8]);c.beginPath();c.moveTo(m.ninja.x,m.ninja.y);for(const p of m.preview.length?m.preview:m.route)c.lineTo(p.x,p.y);c.stroke();c.setLineDash([]);}
 for(const p of m.projectiles){c.save();c.translate(p.x,p.y);c.rotate(m.clock/80);label(c,'✦',0,0,24,'#edf3ff');c.restore();}
 const n=m.ninja,[fill,stroke]=skins[skin]||skins.moon;drawCharacter(c,'ninja',n.x,n.y+6,n.r/30,{time:m.clock,color:fill});if(m.shieldPointers.size&&m.energy>0){c.strokeStyle='#91eeed';c.lineWidth=3;c.beginPath();c.arc(n.x,n.y,30,0,TAU);c.stroke();}if(m.alarm>0){const ratio=m.alarm/([1200,1050,900,800,700][m.difficulty-1]);rounded(c,n.x-25,n.y-38,50,7,3,'#293148');rounded(c,n.x-25,n.y-38,50*Math.min(1,ratio),7,3,'#ffad8b');label(c,'!',n.x,n.y-51,22,'#ffd199');}if(m.hidden)label(c,'HIDDEN',n.x,n.y+30,11,'#8cf1c8');
}
function cone(c,x,y,a,width,r,color){c.fillStyle=color;c.beginPath();c.moveTo(x,y);c.arc(x,y,r,a-width,a+width);c.closePath();c.fill();}
export function renderDentist(canvas,m,{reduceMotion=false,effects='full'}={}){const{c}=prepareCanvas(canvas);drawCareBackdrop(c,'dentist');const pat=m.patient;label(c,pat.name.toUpperCase(),500,38,20,'#dfc8f4');
 drawCharacter(c,'monster',500,330,6.4,{color:pat.color,variant:['buck','dragon','cyclops','fluffy','vampire','triple','slime'].indexOf(pat.kind),mouth:false,time:reduceMotion?0:m.clock,expression:m.complete?'happy':m.reaction==='warning'?'surprise':'happy'});
 // A dedicated mouth close-up. Eyes, silhouette and accessories sit outside treatment hitboxes.
 const skin=pat.color;drawCharacter(c,'monster',72,85,.9,{color:skin,variant:['buck','dragon','cyclops','fluffy','vampire','triple','slime'].indexOf(pat.kind),time:reduceMotion?0:m.clock});c.fillStyle=skin;c.strokeStyle='#d9d8ef';c.lineWidth=3;c.beginPath();if(pat.kind==='slime'){c.moveTo(120,430);c.bezierCurveTo(90,195,310,110,500,120);c.bezierCurveTo(760,80,930,275,875,450);c.quadraticCurveTo(830,615,755,555);c.quadraticCurveTo(690,620,620,562);c.quadraticCurveTo(470,625,390,563);c.quadraticCurveTo(230,620,120,430);}else if(pat.kind==='dragon'||pat.kind==='triple'){c.moveTo(130,390);c.bezierCurveTo(80,250,195,130,310,135);c.lineTo(350,105);c.lineTo(405,140);c.lineTo(475,110);c.lineTo(535,140);c.lineTo(605,105);c.lineTo(660,140);c.bezierCurveTo(860,115,950,330,870,465);c.quadraticCurveTo(735,590,500,575);c.quadraticCurveTo(220,605,130,390);}else if(pat.kind==='vampire'){c.moveTo(120,300);c.lineTo(185,130);c.quadraticCurveTo(500,95,815,130);c.lineTo(880,300);c.lineTo(850,480);c.quadraticCurveTo(500,620,150,480);c.closePath();}else c.ellipse(500,345,395,230,0,0,TAU);c.fill();c.stroke();c.save();c.globalAlpha=.28;c.fillStyle='#f5edd2';for(const sign of [-1,1]){c.beginPath();c.ellipse(500+sign*325,245,27,60,sign*.3,0,TAU);c.fill();}c.restore();if(pat.kind==='dragon'||pat.kind==='triple'){c.strokeStyle='#417e7b88';c.lineWidth=2;for(const side of [-1,1])for(let i=0;i<8;i++){c.beginPath();c.arc(500+side*(290+i%2*25),200+i*36,13,0,Math.PI);c.stroke();}}
 if(pat.kind==='dragon')for(const sign of [-1,1]){c.fillStyle='#edcf98';c.beginPath();c.moveTo(500+sign*300,185);c.lineTo(500+sign*345,70);c.lineTo(500+sign*220,155);c.fill();}
 if(pat.kind==='buck'){c.fillStyle=skin;for(const x of [280,720]){c.beginPath();c.ellipse(x,115,40,95,(x<500?-.3:.3),0,TAU);c.fill();c.fillStyle='#e8b5c7';c.beginPath();c.ellipse(x,105,18,63,(x<500?-.3:.3),0,TAU);c.fill();c.fillStyle=skin;}}
 if(pat.kind==='fluffy')for(let i=0;i<24;i++){const a=i*TAU/24;c.fillStyle=skin;c.strokeStyle='#eed5e7';c.beginPath();c.arc(500+Math.cos(a)*370,335+Math.sin(a)*220,26,0,TAU);c.fill();c.stroke();}
 const eyes=pat.kind==='cyclops'?[500]:[355,645];for(const ex of eyes){c.fillStyle='#fff6dc';c.beginPath();c.ellipse(ex,130,pat.kind==='cyclops'?65:48,42,0,0,TAU);c.fill();c.fillStyle='#3d4564';c.beginPath();c.ellipse(ex+Math.sin((reduceMotion?0:m.clock)/1500)*5,133,13,21,0,0,TAU);c.fill();c.fillStyle='#fff';c.beginPath();c.arc(ex+6,124,5,0,TAU);c.fill();}
 const closed=false;rounded(c,140,180,720,355,85,'#2a1d31','#d7a4bd');rounded(c,172,195,656,40,18,'#cf8b9e','#eab1bd');rounded(c,172,458,656,45,20,'#cf8b9e','#eab1bd');
 if(closed){label(c,'A–CHOO! ✦',500,345,42,'#f8d1df');}else{
 const tongue=m.tongue();rounded(c,tongue.x-tongue.w/2,tongue.y-tongue.h/2,tongue.w,tongue.h,25,'#d27da5');
 for(const t of m.teeth){const p=m.toothPosition(t),extracted=t.tasks.includes('loose')&&t.completed.has('loose'),missing=m.active(t,'missing')||extracted,dirty=m.active(t,'dirt'),progress=t.progress.dirt||0;c.save();c.translate(p.x,p.y);c.rotate(t.angle||t.slotAngle||0);if(missing)rounded(c,-t.w/2,-t.h/2,t.w,t.h,Math.min(15,t.w/3),'#211d36','#a396b8');else drawEnamel(c,t.w,t.h);const chosen=t.tasks.some(k=>!t.completed.has(k)&&DENTAL_TASKS[k].tool===m.tool);if(chosen){c.setLineDash([3,4]);c.strokeStyle='#a6e4d1';c.lineWidth=2;c.strokeRect(-t.w*.62,-t.h*.62,t.w*1.24,t.h*1.24);c.setLineDash([]);}if(missing){c.setLineDash([3,4]);c.strokeStyle='#d8bfed';c.strokeRect(-t.w*.35,-t.h*.35,t.w*.7,t.h*.7);c.setLineDash([]);label(c,extracted?'✓':'?',0,0,22,'#b5a3d5');}if(dirty){c.fillStyle=`rgba(122,151,77,${.8*(1-progress)})`;for(let i=0;i<5;i++){c.beginPath();c.ellipse((i%3-1)*t.w*.22,(Math.floor(i/3)-.5)*20,10,7,i,0,TAU);c.fill();}}if(m.active(t,'plaque')){c.globalAlpha=1-(t.progress.plaque||0);c.fillStyle='#d9b166';c.fillRect(-t.w*.4,t.h*.12,t.w*.8,10);c.globalAlpha=1;}if(m.active(t,'cavity')){c.fillStyle='#8261ac';c.beginPath();c.arc(0,0,Math.max(5,14*(1-(t.progress.cavity||0))),0,TAU);c.fill();}if(m.active(t,'food')||m.active(t,'candy')){label(c,m.active(t,'candy')?'🍬':'🥬',0,0,24);c.setLineDash([3,4]);c.strokeStyle='#8b75ad';c.beginPath();c.arc(0,0,t.w*.28,0,TAU);c.stroke();c.setLineDash([]);}if(m.active(t,'loose')){label(c,t.pullDirection>0?'↓':'↑',0,0,25,'#9b78b4');}if(m.active(t,'polish')){c.fillStyle='#aaa3bf77';c.beginPath();c.ellipse(0,0,t.w*.25,t.h*.2,0,0,TAU);c.fill();}if(t.completed.size===t.tasks.length)label(c,'✦',0,0,23,'#b2b0e4');c.restore();const left=t.tasks.filter(k=>!t.completed.has(k));if(left.length){label(c,left.map(k=>TASK_ICONS[k]).join(' '),p.x,p.y+t.h/2+15,16,'#e0cde8');const current=left.find(k=>(t.progress[k]||0)>0),value=current?t.progress[current]:0;if(value)rounded(c,p.x-t.w/2,p.y-t.h/2-9,t.w*Math.min(1,value),5,2,'#77ddb9');}}
 }
 if(m.reaction==='warning')label(c,'A sneeze is coming… keep your hand steady!',500,85,18,'#ffebac');else if(m.reaction==='giggle')label(c,'Hee hee! Tickly!',500,85,18,'#ffe8bc');
 rounded(c,370,550,260,62,18,'#4e5474','#b7b4d6');label(c,'🦷  NEW-TOOTH TRAY  🦷',500,580,19,'#f6e8ff');
 if(effects!=='off')sparkles(c,{clock:m.clock,bursts:reduceMotion||effects==='reduced'?m.bursts.slice(-1):m.bursts});for(const p of m.pointers.values()){drawTool(c,p.tool,p.x,p.y,.65,{time:reduceMotion?0:m.clock});if(p.tool==='replace'){c.save();c.translate(p.x,p.y);c.rotate(m.replacementAngle);rounded(c,-14,-21,28,42,9,'#fff2e2','#d6bdda');c.restore();}if(p.tool==='water'){c.strokeStyle='#85d9f2';c.lineWidth=2;for(let i=0;i<4;i++){c.beginPath();c.moveTo(p.x-8+i*5,p.y);c.lineTo(p.x-14+i*9,p.y+24+(m.clock/30)%12);c.stroke();}}}
}

function sparkles(c,m){for(const b of m.bursts||[]){const f=(m.clock-b.born)/900;c.globalAlpha=1-f;for(let i=0;i<12;i++){const a=i*TAU/12,r=15+f*55;c.fillStyle=i%2?'#fff2b7':'#a6f3e3';c.beginPath();c.arc(b.x+Math.cos(a)*r,b.y+Math.sin(a)*r-f*25,3*(1-f)+1,0,TAU);c.fill();}c.globalAlpha=1;}}
function environment(c,m,kind){c.save();c.globalAlpha=.16;const theme=m.level.theme;if(kind==='slime'&&theme.includes('Candy')){for(const x of [35,950]){c.strokeStyle='#f9b0d2';c.lineWidth=12;c.beginPath();c.moveTo(x,120);c.lineTo(x,500);c.stroke();for(let y=140;y<490;y+=38){c.strokeStyle='#fff4d3';c.lineWidth=5;c.beginPath();c.moveTo(x-5,y);c.lineTo(x+5,y+15);c.stroke();}}for(const p of [[80,130],[910,180]]){c.fillStyle='#dda4dd';c.beginPath();c.arc(p[0],p[1],24,0,TAU);c.fill();}}else if(kind==='slime'&&theme.includes('Cave')){for(let i=0;i<10;i++){const x=i*110;c.fillStyle=i%2?'#ad9ae9':'#7b9ed5';c.beginPath();c.moveTo(x,65);c.lineTo(x+35,130+i%3*15);c.lineTo(x+65,65);c.fill();}}else if(kind==='slime'&&theme.includes('Orbital')){c.strokeStyle='#87d7ea';c.lineWidth=2;for(let x=30;x<1000;x+=120){c.strokeRect(x,75,85,65);c.beginPath();c.moveTo(x+40,75);c.lineTo(x+40,50);c.stroke();}}else if(kind==='slime'){for(const x of [40,880]){rounded(c,x,100,70,145,12,'#73aeb5','#bce5e4');label(c,'⚗',x+35,172,42,'#c6f1df');}}else if(kind==='ninja'&&theme.includes('Bamboo')){for(const x of [30,55,945,970]){c.strokeStyle='#82c7a6';c.lineWidth=9;c.beginPath();c.moveTo(x,70);c.lineTo(x-12,570);c.stroke();for(let y=100;y<550;y+=70){c.strokeStyle='#a4d5b2';c.lineWidth=3;c.beginPath();c.moveTo(x-12,y);c.lineTo(x+6,y);c.stroke();}}}else if(kind==='ninja'&&theme.includes('Citadel')){c.strokeStyle='#a9a0ec';for(let i=0;i<6;i++)c.strokeRect(80+i*150,65,100,25);}else if(kind==='ninja'){c.fillStyle='#b1acd9';c.beginPath();c.arc(850,70,35,0,TAU);c.fill();for(let x=40;x<1000;x+=140){c.fillStyle='#67658d';c.beginPath();c.moveTo(x,620);c.lineTo(x+55,580);c.lineTo(x+110,620);c.fill();}}c.restore();}
